#include <stdio.h>
/*
 * ex07：结构冒险 —— 单端口存储器导致的取指停顿
 * 背景：五段流水线里 IF 要读指令、MEM 要读写数据。若只有一个存储器端口，
 *       当访存指令进入 MEM 时，紧接着的 IF 就没法同时读指令 → 必须停 1 拍。
 *       解决：指令 cache 与数据 cache 分离（哈佛结构），或加双端口存储。
 * 本程序扫描指令流，统计访存指令造成的结构停顿。
 */
typedef struct {
    const char *name;  /* 助记符 */
    int touches_mem;   /* 是否在 MEM 段访问数据存储器 */
} Insn;

int main(void) {
    Insn prog[] = {
        {"ADD R1,R2,R3", 0},
        {"LW  R4,0(R1)", 1},   /* load：MEM 段读数据 */
        {"ADD R5,R4,R2", 0},
        {"SW  0(R1),R5", 1},   /* store：MEM 段写数据 */
        {"ADD R6,R4,R5", 0},
        {"LW  R7,0(R6)", 1},   /* load */
        {"ADD R8,R7,R6", 0},
    };
    int n = (int)(sizeof(prog) / sizeof(prog[0]));
    int stalls = 0;

    printf("结构冒险(单口存储器)检测：每条访存指令占MEM段，后继IF延后1拍\n");
    for (int i = 0; i < n; i++) {
        if (prog[i].touches_mem) {
            stalls += 1;   /* 单口冲突：IF 让路 1 拍 */
            printf("  %s : 访存占用存储器 -> +1 结构停顿\n", prog[i].name);
        }
    }
    printf("结构停顿总计=%d 拍; 总流水周期=%d (无冒险时=%d)\n",
           stalls, (5 + n - 1) + stalls, 5 + n - 1);
    return 0;
}
